from fastapi import FastAPI
from graphene import ObjectType, Int, String, List, Schema, Field
from fastapi_gql import GQL

SDL = '''
  type User @key(fields: "id") {
    id: Int!
    name: String
  }

  type Query {
    user(id: Int!): User
    users: [User]
  }
'''

users_data = [
    {'id': 1, 'name': 'Alice'},
    {'id': 2, 'name': 'Bob'}
]

class Service(ObjectType):
    sdl = String()

class User(ObjectType):
    id = Int(required=True)
    name = String()

class Query(ObjectType):
    _service = Field(Service)
    user = Field(User, id=Int(required=True))
    users = List(User)

    def resolve__service(self, info):
        return Service(sdl=SDL)

    def resolve_user(self, info, id):
        u = next((u for u in users_data if u['id'] == id), None)
        return User(**u) if u else None

    def resolve_users(self, info):
        return [User(**u) for u in users_data]

schema = Schema(query=Query)
app = FastAPI()
GQL(app, schema=schema)

if __name__ == '__main__':
    import uvicorn
    uvicorn.run(app, port=3001)

