	http.HandleFunc("/federated/users", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		usersRes, _ := graphqlRequest("http://localhost:3001/graphql", "{ users { id name } }")
		reviewsRes, _ := graphqlRequest("http://localhost:3002/graphql", "{ reviews { id text } }")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"users":   usersRes["data"].(map[string]interface{})["users"],
			"reviews": reviewsRes["data"].(map[string]interface{})["reviews"],
		})
	})

	http.ListenAndServe(":3000", nil)
