package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

type Review struct {
	ID       int    `json:"id"`
	Text     string `json:"text"`
	AuthorID int    `json:"authorId"`
}

var users = []User{{ID: 1, Name: "Alice"}, {ID: 2, Name: "Bob"}}
var reviews = []Review{{ID: 1, Text: "Great!", AuthorID: 1}, {ID: 2, Text: "Nice!", AuthorID: 2}}

func main() {
	http.HandleFunc("/federated/user/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		idStr := strings.TrimPrefix(r.URL.Path, "/federated/user/")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		for _, u := range users {
			if u.ID == id {
				var userReviews []Review
				for _, rev := range reviews {
					if rev.AuthorID == id {
						userReviews = append(userReviews, rev)
					}
				}
				json.NewEncoder(w).Encode(map[string]interface{}{
					"id":      u.ID,
					"name":    u.Name,
					"reviews": userReviews,
				})
				return
			}
		}
		w.WriteHeader(http.StatusNotFound)
		json.NewEncoder(w).Encode(map[string]string{"error": "User not found"})
	})

	http.ListenAndServe(":3000", nil)
}

