package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"time"
)

type Service struct {
	Name string `json:"name"`
	URL  string `json:"url"`
}

var services = []Service{
	{Name: "users", URL: "http://localhost:3001/graphql"},
	{Name: "reviews", URL: "http://localhost:3002/graphql"},
}

func checkService(url string) map[string]string {
	client := &http.Client{Timeout: 2 * time.Second}
	body := map[string]string{"query": "{ __typename }"}
	jsonBody, _ := json.Marshal(body)
	resp, err := client.Post(url, "application/json", bytes.NewBuffer(jsonBody))
	if err != nil {
		return map[string]string{"status": "unhealthy"}
	}
	defer resp.Body.Close()
	return map[string]string{"status": "healthy"}
}

func main() {
	http.HandleFunc("/federation/status", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		type ServiceStatus struct {
			Name   string `json:"name"`
			URL    string `json:"url"`
			Status string `json:"status"`
		}
		var results []ServiceStatus
		for _, svc := range services {
			result := checkService(svc.URL)
			results = append(results, ServiceStatus{
				Name:   svc.Name,
				URL:    svc.URL,
				Status: result["status"],
			})
		}
		json.NewEncoder(w).Encode(map[string]interface{}{"services": results})
	})

	http.ListenAndServe(":3000", nil)
}
